package com.yonlab.offlinevoice;
import android.content.Context;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
/** Hash-pinned, bundled Base/Small multilingual Whisper weight sets. */
final class PlusWhisperModels {
 private PlusWhisperModels(){}
 static final String MANIFEST_SHA="b0eeb04f51fbe79894c65172ec3bb9a44f6d0dc941d8150a9318376c15693537";
 static String fingerprint(String id){if(VoiceModelPolicy.WHISPER_BASE.equals(id))return "2e52ee88e6c6a755135091df4e5d636d90415dfa49bf9381497c2ced53256e27";if(VoiceModelPolicy.WHISPER_SMALL.equals(id))return "605b9f688329fde789d291dc98984a5ec34253d274c469c5596f0de9c516425b";throw new IllegalArgumentException("음성 모델을 선택하세요");}
 static File prepare(Context c,String id,SafeModelZip.Cancel cancel)throws Exception{synchronized(KoreanModelStore.class){
  SafeModelZip.check(cancel);String size=VoiceModelPolicy.whisperSize(id);if(!"base".equals(size)&&!"small".equals(size))throw new IOException("Whisper model identity");
  byte[] raw;try(InputStream in=c.getAssets().open("offlinevoice/whisper-modelplus.json");ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){SafeModelZip.check(cancel);if(out.size()+n>65536)throw new IOException("Model manifest size");out.write(b,0,n);}raw=out.toByteArray();}
  if(!MANIFEST_SHA.equals(SafeModelZip.hex(MessageDigest.getInstance("SHA-256").digest(raw))))throw new IOException("Model manifest hash");
  JSONArray specs=new JSONObject(new String(raw,StandardCharsets.UTF_8)).getJSONArray("models");JSONObject spec=null;for(int i=0;i<specs.length();i++)if(id.equals(specs.getJSONObject(i).getString("id")))spec=specs.getJSONObject(i);if(spec==null||!fingerprint(id).equals(spec.getString("fingerprint")))throw new IOException("Model manifest identity");
  Set<String> allowed=new HashSet<>(Arrays.asList(size+"-encoder.int8.onnx",size+"-decoder.int8.onnx",size+"-tokens.txt"));Map<String,SafeModelZip.Expected> expected=new LinkedHashMap<>();JSONArray files=spec.getJSONArray("files");long total=0;for(int i=0;i<files.length();i++){JSONObject row=files.getJSONObject(i);String name=row.getString("name");if(!allowed.contains(name)||!row.getString("asset").equals("offlinevoice/whisper-"+size+"-int8/"+name))throw new IOException("Whisper model path");SafeModelZip.Expected file=new SafeModelZip.Expected(row.getLong("bytes"),row.getString("sha256"));if(expected.put(name,file)!=null)throw new IOException("Duplicate Whisper file");total+=file.bytes;}if(expected.size()!=3||total>SafeModelZip.MAX_UNPACKED)throw new IOException("Whisper model size");
  File base=new File(c.getNoBackupFilesDir(),"offlinevoice-models");if(!base.isDirectory()&&!base.mkdirs())throw new IOException("Model storage");SafeModelZip.cleanupPending(base,cancel);File target=new File(base,"whisper-plus-"+size+"-"+fingerprint(id).substring(0,12));if(SafeModelZip.verify(target,expected,cancel))return target;if(target.exists())SafeModelZip.removeOwned(base,target);if(base.getUsableSpace()<total+16L*1024*1024)throw new IOException("음성 모델 저장 공간을 확인하세요");
  File pending=new File(base,"pending-"+UUID.randomUUID());if(!pending.mkdirs())throw new IOException("Whisper staging");try{for(Map.Entry<String,SafeModelZip.Expected> entry:expected.entrySet()){SafeModelZip.check(cancel);SafeModelZip.Expected specFile=entry.getValue();File file=new File(pending,entry.getKey());MessageDigest hash=MessageDigest.getInstance("SHA-256");long count=0;try(InputStream in=c.getAssets().open("offlinevoice/whisper-"+size+"-int8/"+entry.getKey());FileOutputStream out=new FileOutputStream(file)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){SafeModelZip.check(cancel);count+=n;if(count>specFile.bytes)throw new IOException("Whisper file size");hash.update(b,0,n);out.write(b,0,n);}out.getFD().sync();}if(count!=specFile.bytes||!specFile.sha256.equals(SafeModelZip.hex(hash.digest())))throw new IOException("Whisper file hash");}
   if(!SafeModelZip.verify(pending,expected,cancel)||target.exists()||!pending.renameTo(target))throw new IOException("Whisper commit");return target;
  }finally{if(pending.exists())SafeModelZip.removeOwned(base,pending);}
 }}
}
